<body>
<aside class="hud" aria-label="Simulation controls">
<div class="eyebrow">COMMON GROUND / 01</div><h1>A day at the office.</h1><p class="subtitle">Six floors. A hundred possible stories.</p>
<div class="clock" id="time">7:30 AM</div><div class="dayrow"><span id="day">MONDAY · DAY 1</span><span class="live" id="phase"><i class="dot"></i>Before hours</span></div>
<div class="control"><label for="speed">Pace of the day <span id="speed-label">120× realtime</span></label><input id="speed" type="range" min="0" max="100" step="1" value="75"><div class="rangeends"><span>1× · TAKE A LOOK</span><span>600× · FAST FORWARD</span></div></div>
<div class="control"><label for="occupancy"><span id="occupancy-label">Occupancy: 45 / 100 people</span></label><input id="occupancy" type="range" min="1" max="100" value="45"><div class="rangeends"><span>QUIET</span><span>BUSY</span></div></div>
<div class="toolbar"><button id="pause" type="button">Pause</button><button id="restart" type="button">New day</button></div>
